def build(root: ET.Element, item: dict) -> None:
	for fact in item['chromosomes']:
		model = chromosomes.Chromosome(tuple(chromosomes.Segment(*region) for region in fact['regions']), fact['centromere_after'])
		part = chromosomes.chromosome_path_part(fact['id'], model, f"M {fact['x']} {fact['start']} V {fact['end']}", thickness=34, labels=False)
		body = ET.fromstring(part.fragment)
		paint = next(e for e in body if e.get('clip-path'))
		for band in fact['bands']:
			ET.SubElement(paint, 'path', band)
		slot = next(e for e in root.iter() if e.get('data-slot') == fact['id'])
		slot.append(body)


def main(output_root: pathlib.Path) -> None:
	for item in FIGURES:
		root = ET.fromstring(item['template'])
		build(root, item)
		for element in root.iter():
			if not element.tag.startswith('{'):
				element.tag = '{http://www.w3.org/2000/svg}' + element.tag
		ET.register_namespace('', 'http://www.w3.org/2000/svg')
		path = output_root / item['path']
		path.parent.mkdir(parents=True, exist_ok=True)
		path.write_text(ET.tostring(root, encoding='unicode'), encoding='utf-8')


if __name__ == '__main__':
	import sys
	main(pathlib.Path(sys.argv[1]) if len(sys.argv) > 1 else pathlib.Path('.'))
